    private static MagazineDetailsModel? CreateExtra(string slug)
    {
        var article = ExtraArticles.FirstOrDefault(item => string.Equals(item.Slug, slug, StringComparison.OrdinalIgnoreCase));
        if (article is null) return null;
        return Create(slug, article.Category, article.Title, article.Summary, article.Image, [
            new("overview", "موضوع را از کجا شروع کنیم؟", article.Summary + " برای رسیدن به انتخابی دقیق، ابتدا نیاز واقعی، شیوه استفاده و مشخصات قابل سنجش را از ظاهر و تبلیغات جدا کنید."),
            new("details", "جزئیات مهم در بررسی", "مشخصات رسمی مدل، کیفیت ساخت، تناسب ابعاد، نوع موتور و شرایط خدمات را کنار هم قرار دهید. هیچ ویژگی به‌تنهایی نشان‌دهنده مناسب‌بودن یک ساعت برای همه افراد نیست."),
            new("checklist", "چک‌لیست پیش از تصمیم", "مدل‌ها را در شرایط یکسان مقایسه کنید، پرسش‌های خود را یادداشت کنید و پیش از پرداخت درباره اصالت، ضمانت، امکان تنظیم بند و شرایط تعویض اطلاعات روشن بگیرید.")
        ]);
    }

